package com.corecs.solid.analyzer;import com.corecs.solid.model.*;import com.corecs.solid.rules.*;import java.util.*;import org.springframework.stereotype.Service;
@Service public class SolidAnalyzer {private final List<SolidRule> rules=List.of(new SrpRule(),new OcpRule(),new LspRule(),new IspRule(),new DipRule());public AnalysisResult analyze(List<ClassInfo> classes){List<Issue> issues=new ArrayList<>();rules.forEach(r->issues.addAll(r.analyze(classes)));List<DependencyEdge> edges=new ArrayList<>();for(var c:classes)for(var d:c.dependencies())if(classes.stream().anyMatch(x->x.name().equals(d)))edges.add(new DependencyEdge(c.name(),d,"dependency"));for(var c:classes)if(c.parent()!=null)edges.add(new DependencyEdge(c.name(),c.parent(),"extends"));return new AnalysisResult(classes,issues,edges,classes.size(),classes.stream().mapToInt(x->x.methods().size()).sum());}}
